import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt', 'html'}

os.makedirs(UPLOAD_DIR, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_metadata(metadata_str):
    """Remove potentially dangerous characters from metadata fields."""
    # Strip null bytes and control characters
    cleaned = ''.join(c for c in metadata_str if ord(c) >= 32 and ord(c) != 127)
    return cleaned[:256]

@app.route('/api/v2/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '' or not allowed_file(file.filename):
        return jsonify({'error': 'Invalid file type'}), 400

    output_format = request.form.get('format', 'pdf')
    if output_format not in ('pdf', 'png', 'jpg'):
        return jsonify({'error': 'Unsupported output format'}), 400

    # Optional: user-supplied title for the PDF metadata
    custom_title = request.form.get('title', '')
    if custom_title:
        custom_title = sanitize_metadata(custom_title)

    # Save uploaded file
    job_id = hashlib.md5(f"{file.filename}{time.time()}".encode()).hexdigest()
    input_path = os.path.join(UPLOAD_DIR, f"{job_id}_{secure_filename(file.filename)}")
    file.save(input_path)

    output_filename = f"{job_id}_output.{output_format}"
    output_path = os.path.join(UPLOAD_DIR, output_filename)

    try:
        # Build conversion command using LibreOffice
        base_cmd = f"libreoffice --headless --convert-to {output_format}"

        if custom_title and output_format == 'pdf':
            # Set PDF metadata title via macro
            base_cmd += f" --infilter='writer_pdf_Export' -env:UserInstallation=file:///tmp/.libreoffice"
            # Pass title through environment for the macro
            env = os.environ.copy()
            env['PDF_TITLE'] = custom_title
        else:
            env = os.environ.copy()

        # Append output directory and input file
        cmd = f"{base_cmd} --outdir {UPLOAD_DIR} {input_path}"

        # Execute conversion
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=60,
            env=env
        )

        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'details': result.stderr.decode()[:200]}), 500

        # LibreOffice names output based on input filename
        actual_output = input_path.rsplit('.', 1)[0] + f'.{output_format}'
        if os.path.exists(actual_output):
            os.rename(actual_output, output_path)

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        return send_file(output_path, as_attachment=True, download_name=output_filename)

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.remove(input_path)

@app.route('/api/v2/batch', methods=['POST'])
def batch_convert():
    """Batch conversion endpoint - accepts JSON with URLs to fetch and convert."""
    data = request.get_json()
    if not data or 'urls' not in data:
        return jsonify({'error': 'Missing urls field'}), 400

    # Validate URLs are from allowed domains
    allowed_domains = os.environ.get('ALLOWED_FETCH_DOMAINS', 'internal.corp.net').split(',')
    results = []
    for url in data['urls'][:10]:
        domain = url.split('/')[2] if len(url.split('/')) > 2 else ''
        if not any(domain.endswith(d.strip()) for d in allowed_domains):
            results.append({'url': url, 'status': 'blocked', 'reason': 'domain not allowed'})
            continue
        results.append({'url': url, 'status': 'queued'})

    return jsonify({'batch_id': hashlib.md5(str(time.time()).encode()).hexdigest(), 'results': results})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
